using System;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
namespace Shixun {
public sealed class CredentialDialog:Form {
 readonly ComboBox method=new ComboBox(),mode=new ComboBox(),contentType=new ComboBox();
 readonly TextBox token=new TextBox(),user=new TextBox(),password=new TextBox(),body=new TextBox();
 readonly DataGridView grid=new DataGridView();
 public RequestProfile Result;
 public CredentialDialog(RequestProfile current,string title){Text="请求与凭据 · "+title;Width=820;Height=720;MinimumSize=new Size(700,600);StartPosition=FormStartPosition.CenterParent;Font=new Font("Microsoft YaHei UI",10);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=11,Padding=new Padding(20),AutoScroll=true};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,145));layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));Controls.Add(layout);method.Items.AddRange(new object[]{"GET","POST"});method.DropDownStyle=ComboBoxStyle.DropDownList;method.SelectedItem=current.method;mode.Items.AddRange(new object[]{"none","bearer","basic"});mode.DropDownStyle=ComboBoxStyle.DropDownList;mode.SelectedItem=current.mode;token.UseSystemPasswordChar=true;password.UseSystemPasswordChar=true;token.Text=current.token;user.Text=current.username;password.Text=current.password;contentType.Items.AddRange(new object[]{"application/json","text/plain","application/x-www-form-urlencoded"});contentType.Text=current.contentType;body.Multiline=true;body.ScrollBars=ScrollBars.Vertical;body.Text=current.body;body.Height=65;
 Add(layout,"请求方法",method,0);Add(layout,"认证模式",mode,1);Add(layout,"Bearer Token",token,2);Add(layout,"Basic 用户名",user,3);Add(layout,"Basic 密码",password,4);var note=new Label{AutoSize=true,MaximumSize=new Size(610,0),Text="可同时添加多个参数：header 请求头、query 查询参数、path 路径占位值、form 表单。路径使用 {参数名}。字段值可能包含密钥，仅保存在本机加密数据中；Cookie 可作为请求头。",Padding=new Padding(0,8,0,8)};layout.Controls.Add(note,0,5);layout.SetColumnSpan(note,2);grid.AutoGenerateColumns=false;grid.AllowUserToAddRows=true;grid.AllowUserToDeleteRows=true;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.Height=185;grid.RowHeadersWidth=25;var position=new DataGridViewComboBoxColumn{Name="place",HeaderText="位置"};position.Items.AddRange("header","query","path","form");grid.Columns.Add(position);grid.Columns.Add(new DataGridViewTextBoxColumn{Name="name",HeaderText="参数名"});grid.Columns.Add(new DataGridViewTextBoxColumn{Name="value",HeaderText="参数值（本机可见）"});foreach(var f in current.fields)grid.Rows.Add(f.place,f.name,f.value);layout.Controls.Add(grid,0,6);layout.SetColumnSpan(grid,2);Add(layout,"POST Content-Type",contentType,7);Add(layout,"POST 请求体",body,8);var reminder=new Label{AutoSize=true,Text="表单字段优先于原始请求体。Token/密码默认遮罩；任意参数值仅在此原生窗口编辑，不发给网页。"};layout.Controls.Add(reminder,0,9);layout.SetColumnSpan(reminder,2);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true,FlowDirection=FlowDirection.RightToLeft};var ok=new Button{Text="加密保存",AutoSize=true};var cancel=new Button{Text="取消",DialogResult=DialogResult.Cancel,AutoSize=true};var clear=new Button{Text="清除全部认证",AutoSize=true};actions.Controls.Add(ok);actions.Controls.Add(cancel);actions.Controls.Add(clear);layout.Controls.Add(actions,0,10);layout.SetColumnSpan(actions,2);AcceptButton=ok;CancelButton=cancel;ok.Click+=delegate{try{grid.EndEdit();var result=new RequestProfile{method=Convert.ToString(method.SelectedItem),mode=Convert.ToString(mode.SelectedItem),token=token.Text,username=user.Text,password=password.Text,body=body.Text,contentType=contentType.Text};foreach(DataGridViewRow row in grid.Rows){if(row.IsNewRow)continue;string name=Convert.ToString(row.Cells["name"].Value);if(String.IsNullOrWhiteSpace(name))continue;result.fields.Add(new RequestField{place=Convert.ToString(row.Cells["place"].Value),name=name.Trim(),value=Convert.ToString(row.Cells["value"].Value)});}Transport.ValidateProfile(result);Result=result;DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(ex is SafeError?ex.Message:"请检查参数配置。",Text);}};clear.Click+=delegate{if(MessageBox.Show("清除此源全部认证和自定义参数？",Text,MessageBoxButtons.OKCancel)!=DialogResult.OK)return;Result=new RequestProfile();DialogResult=DialogResult.OK;Close();};}
 static void Add(TableLayoutPanel panel,string title,Control control,int row){panel.Controls.Add(new Label{Text=title,AutoSize=true,Padding=new Padding(0,7,0,0)},0,row);control.Dock=DockStyle.Top;panel.Controls.Add(control,1,row);}
}
}
